export function getBirdAudioUri(birdId: string): string | null {
  const file = BIRD_AUDIO_FILES[birdId];
  if (!file) return null;
  return `${DEFAULT_AUDIO_BASE_URL.replace(/\/+$/, '')}/${file}`;
}
